-- Publish step: makes ONLY the lessons named below visible to learners.
--
-- Run it only for lessons that have been checked against the official WA Driver
-- Guide (the approval gate). Lessons that are not named stay hidden, so
-- publishing one checked lesson never publishes other unchecked drafts.
--
-- How to use: do not edit this file. Fill in the list in the copy you run.
--   Local (Git Bash, from the repo root):
--     sed "s/array\[\]::text\[\]/array['wa-traffic-signs','wa-hazards']/" supabase/publish.sql \
--       | docker exec -i supabase_db_SuperDriver psql -U postgres -v ON_ERROR_STOP=1
--   Hosted: paste this file into the Supabase SQL editor, put the lesson IDs in
--     the list there, and run it.
-- With the list left empty it refuses and publishes nothing.
--
-- It also refuses (and publishes nothing) if a named lesson does not exist, or
-- if a question in the named lessons does not have exactly one correct choice
-- or has fewer than 2 choices (the "at least one correct" rule cannot be a
-- table constraint).
--
-- To take a lesson down again: set status back to 'draft' on its lesson,
-- sections and questions.

do $$
declare
  -- The lessons to publish, for example: array['wa-traffic-signs','wa-hazards']
  lesson_ids text[] := array[]::text[];
  bad text;
begin
  if cardinality(lesson_ids) = 0 then
    raise exception 'Nothing to publish: put lesson IDs in lesson_ids at the top of publish.sql';
  end if;

  select string_agg(t.x, ', ') into bad
    from unnest(lesson_ids) as t(x)
   where not exists (select 1 from public.lessons l where l.id = t.x);
  if bad is not null then
    raise exception 'Refusing to publish: no lesson with id: %', bad;
  end if;

  select string_agg(q.id, ', ') into bad
    from public.questions q
    join public.sections s on s.id = q.section_id
   where s.lesson_id = any (lesson_ids)
     and (select count(*) from public.choices c
           where c.question_id = q.id and c.is_correct) <> 1;
  if bad is not null then
    raise exception 'Refusing to publish: questions without exactly one correct choice: %', bad;
  end if;

  select string_agg(q.id, ', ') into bad
    from public.questions q
    join public.sections s on s.id = q.section_id
   where s.lesson_id = any (lesson_ids)
     and (select count(*) from public.choices c where c.question_id = q.id) < 2;
  if bad is not null then
    raise exception 'Refusing to publish: questions with fewer than 2 choices: %', bad;
  end if;

  update public.lessons  set status = 'published' where id = any (lesson_ids);
  update public.sections set status = 'published' where lesson_id = any (lesson_ids);
  update public.questions set status = 'published'
   where section_id in (select id from public.sections where lesson_id = any (lesson_ids));

  raise notice 'Published: %', array_to_string(lesson_ids, ', ');
end $$;
